    html: "<div class=\"flex gap-8\">\n      <div class=\"border-r-2 border-black py-2\">\n        <div role=\"tablist\" class=\"-mr-0.5 flex flex-col\">\n          <button\n            role=\"tab\"\n            aria-selected=\"true\"\n            class=\"border-2 border-black bg-yellow-200 px-6 py-2 font-semibold text-black focus:ring-2 focus:ring-yellow-300 focus:outline-0\"\n          >\n            General\n          </button>\n\n          <button\n            role=\"tab\"\n            aria-selected=\"false\"\n            class=\"border-2 border-transparent px-6 py-2 font-semibold text-black hover:bg-black hover:text-white focus:ring-2 focus:ring-yellow-300 focus:outline-0\"\n          >\n            Privacy\n          </button>\n\n          <button\n            role=\"tab\"\n            aria-selected=\"false\"\n            class=\"border-2 border-transparent px-6 py-2 font-semibold text-black hover:bg-black hover:text-white focus:ring-2 focus:ring-yellow-300 focus:outline-0\"\n          >\n            Security\n          </button>\n        </div>\n      </div>\n\n      <div role=\"tabpanel\" class=\"flex-1 py-2\">\n        <p class=\"text-black\">\n          Lorem, ipsum dolor sit amet consectetur adipisicing elit. Deserunt similique, quae hic\n          dicta quo facere facilis praesentium a sunt, est quia pariatur nam, modi aut minus iste\n          odio consectetur molestias iusto cupiditate ullam laborum veniam quos officia. Quos,\n          temporibus perspiciatis!\n        </p>\n      </div>\n    </div>",
